-- 2) New world: Pixel Arcade
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`tagline`=VALUES(`tagline`),`description`=VALUES(`description`),`animation_key`=VALUES(`animation_key`),`font_style`=VALUES(`font_style`),`ambient_preset`=VALUES(`ambient_preset`),`theme_config`=VALUES(`theme_config`),`is_active`=1;

-- 3) World/occasion ambient assets: point every row at its SVG (image_url) and add the new ones
ON DUPLICATE KEY UPDATE `image_url`=VALUES(`image_url`),`metadata_json`=VALUES(`metadata_json`),`is_active`=1;

-- 4) Occasions. Dates are IST; start = event minus 8 days (matches the 8-day activation rule). Eid / Holi follow the moon & panchang: verify before launch.
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`eyebrow`=VALUES(`eyebrow`),`headline`=VALUES(`headline`),`subtitle`=VALUES(`subtitle`),`motif_key`=VALUES(`motif_key`),`primary_color`=VALUES(`primary_color`),`accent_color`=VALUES(`accent_color`),`background_color`=VALUES(`background_color`),`banner_image_url`=VALUES(`banner_image_url`),`start_date`=VALUES(`start_date`),`end_date`=VALUES(`end_date`),`theme_config`=VALUES(`theme_config`);

-- Existing occasions: attach SVG kits; switch Winter Frost on (its window opens 2026-12-01, so it activates 2026-11-23 under the 8-day rule)
